// Small read-only XLSX reader for standard worksheet values. No formulas are evaluated.
async function readOrderWorkbook(buffer){
  const data=new Uint8Array(buffer),view=new DataView(buffer),u16=p=>view.getUint16(p,true),u32=p=>view.getUint32(p,true);
  let end=-1;for(let p=data.length-22;p>=Math.max(0,data.length-65558);p--){if(u32(p)===0x06054b50){end=p;break}}
  if(end<0)throw Error('这不是有效的 .xlsx 文件');
  const files=new Map();let pos=u32(end+16),total=u16(end+10);
  for(let i=0;i<total;i++){if(u32(pos)!==0x02014b50)throw Error('Excel 压缩包目录无效');const method=u16(pos+10),compressed=u32(pos+20),nameLen=u16(pos+28),extra=u16(pos+30),comment=u16(pos+32),local=u32(pos+42),name=new TextDecoder().decode(data.slice(pos+46,pos+46+nameLen));files.set(name,{method,compressed,local});pos+=46+nameLen+extra+comment}
  async function content(path){const f=files.get(path);if(!f)throw Error('Excel 文件缺少组件：'+path);const start=f.local+30+u16(f.local+26)+u16(f.local+28),bytes=data.slice(start,start+f.compressed);if(f.method===0)return new TextDecoder().decode(bytes);if(f.method!==8)throw Error('暂不支持此 Excel 压缩格式');const stream=new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));return new TextDecoder().decode(await new Response(stream).arrayBuffer())}
  const xml=s=>{const d=new DOMParser().parseFromString(s,'application/xml');if(d.querySelector('parsererror'))throw Error('无法读取 Excel XML');return d};
  const all=(node,name)=>Array.from(node.getElementsByTagName('*')).filter(e=>e.localName===name),child=(node,name)=>Array.from(node?.children||[]).find(e=>e.localName===name);
  const workbook=xml(await content('xl/workbook.xml')),rels=xml(await content('xl/_rels/workbook.xml.rels'));
  let strings=[];if(files.has('xl/sharedStrings.xml')){const s=xml(await content('xl/sharedStrings.xml'));strings=all(s,'si').map(si=>all(si,'t').map(t=>t.textContent).join(''))}
  const sheets=all(workbook,'sheet').map(s=>{const id=s.getAttribute('r:id')||s.getAttributeNS('http://schemas.openxmlformats.org/officeDocument/2006/relationships','id');const rel=all(rels,'Relationship').find(r=>r.getAttribute('Id')===id);if(!rel)return null;let target=rel.getAttribute('Target').replace(/^\/+/, '').replace(/^\.\//,'');let path=target.startsWith('xl/')?target:'xl/'+target;return {name:s.getAttribute('name')||'',path}}).filter(Boolean);
  async function readSheet(sheet){const doc=xml(await content(sheet.path)),rows=[];for(const r of all(doc,'row')){const rowNum=Number(r.getAttribute('r'));if(!rowNum||rowNum>100000)continue;const cells=[];for(const c of Array.from(r.children).filter(e=>e.localName==='c')){const ref=c.getAttribute('r')||'',letters=(ref.match(/^[A-Z]+/)||[])[0];if(!letters)continue;let col=0;for(const letter of letters)col=col*26+letter.charCodeAt(0)-64;col--;if(col>60)continue;const type=c.getAttribute('t'),v=child(c,'v'),inline=child(c,'is');let value=v?.textContent??'';if(type==='s')value=strings[Number(value)]??'';else if(type==='inlineStr')value=all(inline,'t').map(t=>t.textContent).join('');else if(type==='b')value=value==='1';else if(type!=='str'&&type!=='e'&&value!==''&&!Number.isNaN(Number(value)))value=Number(value);cells[col]=value}rows[rowNum-1]=cells}return rows}
  const out=[];for(const s of sheets)out.push({...s,rows:await readSheet(s)});return out;
}
